#include "cut-color-fixture.hpp"
#include "polygon-color-uv.hpp"
#include "dome/uv.hpp"
#include <cstdlib>
#include <iostream>
#include <new>
namespace {thread_local bool tracking=false;bool hit=false;size_t calls=0,deny=SIZE_MAX;void require(bool pass,const char *why){if(!pass)throw std::runtime_error(why);}}
[[gnu::noinline]] void *operator new(size_t size){if(tracking&&++calls>=deny){hit=true;throw std::bad_alloc();}if(auto p=std::malloc(size?size:1))return p;throw std::bad_alloc();}
[[gnu::noinline]] void *operator new[](size_t size){return ::operator new(size);}
[[gnu::noinline]] void operator delete(void *p)noexcept{std::free(p);}[[gnu::noinline]] void operator delete[](void *p)noexcept{std::free(p);}[[gnu::noinline]] void operator delete(void *p,size_t)noexcept{std::free(p);}[[gnu::noinline]] void operator delete[](void *p,size_t)noexcept{std::free(p);}
int main(int argc,char **argv)try{
 using namespace dome;const size_t shard=argc==3?std::stoul(argv[1]):0,shards=argc==3?std::stoul(argv[2]):1;require((argc==1||argc==3)&&shards&&shards<=32&&shard<shards,"Choose bounded complete operation shard");
 auto original=cut_color_fixture::scene(true);auto &object=original.active();object.painted=object.painted->snapshot();Brush brush;brush.from=brush.to={0,0,.25f};brush.radius=.3f;PaintSettings ink;ink.front_only=false;ink.flow=.7f;ink.mask=.4f;
 for(auto channel:{PaintChannel::Color,PaintChannel::Metallic,PaintChannel::Roughness,PaintChannel::Emission,PaintChannel::Mask}){ink.channel=channel;object.painted->begin_stroke();object.painted->stamp(brush,ink);object.painted->end_stroke();}object.painted->layer_properties("Every channel retained",true,.6f);object.painted->add_layer("Hidden original layer");object.painted->layer_properties("Hidden original layer",false,.3f);
 UvWorkspace uv(object.painted->mesh(),64);uv.edit(UvAction::Move,1.f/64.f,0);auto target=uv.view().mesh;auto mapping=uv.view().source_vertices;const auto before=original.encode();const auto field=object.polygon->colors;const auto basis=field->source_owner();auto operation=[&](Scene &scene){detail::reparameterize_raw_polygon_colors(scene,object.id,*target,*mapping);};
 auto full=original.snapshot();operation(full);const auto expected=full.encode();auto measured=original.snapshot();calls=0;hit=false;deny=SIZE_MAX;tracking=true;operation(measured);tracking=false;const auto count=calls;require(count>1&&count<65536&&measured.encode()==expected,"Actual complete UV operation allocation count is bounded and deterministic");
 const size_t first=1+count*shard/shards,last=count*(shard+1)/shards;require(first<=last,"Every shard contains measured real allocation boundaries");std::cout<<"Raw UV allocations "<<count<<" actual range "<<first<<".."<<last<<std::endl;size_t refused=0,complete=0;
 for(size_t at=first;at<=last;++at){auto candidate=original.snapshot();auto authority=candidate.active().polygon;auto mesh=candidate.active().painted->mesh_owner();calls=0;hit=false;deny=at;bool failed=false;tracking=true;try{operation(candidate);}catch(const std::bad_alloc&){failed=true;}tracking=false;require(hit,"Every measured allocation is actually denied persistently");if(failed){++refused;require(candidate.encode()==before&&candidate.active().polygon==authority&&candidate.active().painted->mesh_owner()==mesh,"Failed UV operation retains exact original paint, corner authority, geometry and full capsule state");}else{++complete;require(candidate.encode()==expected,"Optional cache denial may only yield the complete exact accepted endpoint");}require(candidate.active().polygon->colors==field&&candidate.active().polygon->colors->source_owner()==basis,"Every failure/success retains the actual original immutable RGBA basis owner");auto retry=original.snapshot();operation(retry);require(retry.encode()==expected&&original.encode()==before&&full.encode()==expected,"A real complete UV operation retries after every denial; immutable input and prepared baseline stay exact");if((at&31)==0)std::cout<<"Reached raw UV allocation "<<at<<std::endl;}
 std::cout<<"PASS "<<refused<<" exact refusals and "<<complete<<" complete optional-cache outcomes in "<<first<<".."<<last<<" of "<<count<<" actual whole UV allocations\n";return 0;
}catch(const std::exception &e){tracking=false;std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
